+@page "/board"
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h1>Project Board</h1>
+
+@if (isLoading)
+{
+    <p><em>Loading tasks...</em></p>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+else
+{
+    <!-- Stats Bar -->
+    <div class="stats-bar">
+        <span class="stat-item"><strong>Total:</strong> @allTasks.Count</span>
+        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
+        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
+        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
+        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @allTasks.Count(t => t.DueDate < DateTime.Today)</span>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="search-bar">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="searchQuery" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="kanban-board">
+        @foreach (var column in columns)
+        {
+            var tasks = GetFilteredColumnTasks(column);
+            <div class="kanban-column">
+                <div class="column-header">
+                    <h3>@column <span class="badge bg-secondary">@tasks.Count</span></h3>
+                </div>
+                <div class="column-body">
+                    @foreach (var task in tasks)
+                    {
+                        <div class="task-card">
+                            <div class="task-title">@task.Title</div>
+                            <div class="task-assignee">@task.Assignee</div>
+                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
+                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
+                            <div class="task-actions">
+                                @if (GetColumnIndex(column) > 0)
+                                {
+                                    <button class="btn btn-sm btn-outline-secondary"
+                                            @onclick="() => MoveTask(task.Id, columns[GetColumnIndex(column) - 1])">
+                                        &larr; Move Left
+                                    </button>
+                                }
+                                @if (GetColumnIndex(column) < columns.Length - 1)
+                                {
+                                    <button class="btn btn-sm btn-outline-secondary"
+                                            @onclick="() => MoveTask(task.Id, columns[GetColumnIndex(column) + 1])">
+                                        Move Right &rarr;
+                                    </button>
+                                }
+                            </div>
+                        </div>
+                    }
+                </div>
+
+                @if (showAddForm == column)
+                {
+                    <div class="add-task-form">
+                        <input type="text" class="form-control mb-1" placeholder="Title"
+                               @bind="newTitle" />
+                        <input type="text" class="form-control mb-1" placeholder="Assignee"
+                               @bind="newAssignee" />
+                        <select class="form-select mb-1" @bind="newPriority">
+                            <option value="High">High</option>
+                            <option value="Medium">Medium</option>
+                            <option value="Low">Low</option>
+                        </select>
+                        <input type="date" class="form-control mb-1" @bind="newDueDate" />
+                        <div class="form-buttons">
+                            <button class="btn btn-primary btn-sm" @onclick="() => SaveTask(column)">Save</button>
+                            <button class="btn btn-secondary btn-sm" @onclick="CancelAdd">Cancel</button>
+                        </div>
+                    </div>
+                }
+                else
+                {
+                    <button class="btn btn-outline-primary btn-sm add-task-btn"
+                            @onclick="() => ShowAddForm(column)">
+                        + Add Task
+                    </button>
+                }
+            </div>
+        }
+    </div>
+}
+
+<style>
+    .stats-bar {
+        display: flex;
+        gap: 1.5rem;
+        padding: 0.75rem 1rem;
+        background: #f8f9fa;
+        border-radius: 0.5rem;
+        margin-bottom: 1rem;
+        flex-wrap: wrap;
+    }
+
+    .stat-overdue {
+        color: #dc3545;
+    }
+
+    .search-bar {
+        margin-bottom: 1rem;
+        max-width: 400px;
+    }
+
+    .kanban-board {
+        display: flex;
+        gap: 1rem;
+        align-items: flex-start;
+    }
+
+    .kanban-column {
+        flex: 1;
+        background: #f1f3f5;
+        border-radius: 0.5rem;
+        padding: 0.75rem;
+        min-width: 250px;
+    }
+
+    .column-header h3 {
+        font-size: 1.1rem;
+        margin-bottom: 0.5rem;
+    }
+
+    .task-card {
+        background: #fff;
+        border: 1px solid #dee2e6;
+        border-radius: 0.375rem;
+        padding: 0.75rem;
+        margin-bottom: 0.5rem;
+    }
+
+    .task-title {
+        font-weight: 600;
+        margin-bottom: 0.25rem;
+    }
+
+    .task-assignee {
+        font-size: 0.85rem;
+        color: #6c757d;
+        margin-bottom: 0.25rem;
+    }
+
+    .task-due {
+        font-size: 0.85rem;
+        color: #495057;
+        margin-top: 0.25rem;
+    }
+
+    .priority-badge {
+        display: inline-block;
+        padding: 0.15rem 0.5rem;
+        border-radius: 0.25rem;
+        font-size: 0.75rem;
+        font-weight: 600;
+        color: #fff;
+    }
+
+    .priority-high {
+        background-color: #dc3545;
+    }
+
+    .priority-medium {
+        background-color: #ffc107;
+        color: #212529;
+    }
+
+    .priority-low {
+        background-color: #198754;
+    }
+
+    .task-actions {
+        margin-top: 0.5rem;
+        display: flex;
+        gap: 0.25rem;
+    }
+
+    .add-task-form {
+        padding: 0.75rem;
+        background: #fff;
+        border: 1px solid #dee2e6;
+        border-radius: 0.375rem;
+        margin-top: 0.5rem;
+    }
+
+    .form-buttons {
+        display: flex;
+        gap: 0.5rem;
+    }
+
+    .add-task-btn {
+        width: 100%;
+        margin-top: 0.5rem;
+    }
+</style>
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private bool isLoading = true;
+    private string? errorMessage;
+    private string searchQuery = string.Empty;
+
+    private string? showAddForm;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    private static readonly string[] columns = { "To Do", "In Progress", "Done" };
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status) =>
+        allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrEmpty(searchQuery) ||
+                        t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private int GetColumnIndex(string column) => Array.IndexOf(columns, column);
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = allTasks.First(t => t.Id == taskId);
+            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private void ShowAddForm(string column)
+    {
+        showAddForm = column;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd()
+    {
+        showAddForm = null;
+    }
+
+    private async Task SaveTask(string column)
+    {
+        if (string.IsNullOrWhiteSpace(newTitle))
+            return;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
+            allTasks.Add(created);
+            showAddForm = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
+

